module QUBODecomposition

import MathOptInterface as MOI
import QUBODrivers
import QUBOTools
import Random
import Distributed
const VI = MOI.VariableIndex
# The version constant must invalidate cached code when only Project.toml changes.
Base.include_dependency(joinpath(@__DIR__, "..", "Project.toml"))
const PACKAGE_VERSION = pkgversion(@__MODULE__)

# The generated storage owns MOI copying, fixed-variable reconstruction and starts.
# The public composite wraps it so its keyword constructor and validation do not
# overwrite methods generated by @setup during precompilation.
QUBODrivers.@setup ModelStorage begin
    name = "QUBODecomposition model storage"
    version = PACKAGE_VERSION
end

include("optimizer.jl")
include("solve.jl")
include("serial.jl")
include("execution.jl")
include("components.jl")
include("voting.jl")
include("articulation.jl")
include("pruning.jl")
include("separator.jl")
include("consensus.jl")
include("coarse.jl")

end
